"use client";

/* ─────────────────────────────────────────────────────────
 * SPLIT PANE: desktop-grade resizable dual surface
 *
 *   divider    1px thin line border with a centered grab pill;
 *              hover expands the line to an active primary accent
 *   drag       zero-lag direct DOM updates; dragging beyond
 *              min/max limits introduces logarithmic rubber-band
 *              resistance
 *   spring     releasing past boundary limits triggers an
 *              analytical WAAPI damped harmonic spring back
 *              to the boundary threshold
 *   snapping   double-clicking the divider smoothly cycles
 *              between 50%, 25%, and 75% preset layouts
 *   collapse   built-in controls fold either pane to 0 width,
 *              docking the thin line divider flush to the edge
 *   touch      expanded touch targets enable fluid dragging on
 *              mobile devices
 *
 * Fully accessible separator semantics with keyboard step.
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import { ChevronLeft, ChevronRight, GripVertical } from "lucide-react";
import {
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import { useSplitPane } from "./use-split-pane";

export interface SplitPaneProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  first: React.ReactNode;
  second: React.ReactNode;
  split?: number;
  defaultSplit?: number;
  minSize?: number;
  maxSize?: number;
  orientation?: "horizontal" | "vertical";
  collapsible?: boolean;
  disabled?: boolean;
  onSplitChange?: (split: number) => void;
  onSplitCommit?: (split: number) => void;
}

export function SplitPane({
  first,
  second,
  split,
  defaultSplit = 50,
  minSize = 15,
  maxSize = 85,
  orientation = "horizontal",
  collapsible = true,
  disabled = false,
  onSplitChange,
  onSplitCommit,
  className = "",
  ...props
}: SplitPaneProps) {
  const reduced = useInteractionReducedMotion();
  const isHorizontal = orientation !== "vertical";

  const pane = useSplitPane({
    orientation,
    split,
    defaultSplit,
    minSize,
    maxSize,
    disabled,
    reduced,
    onChange: onSplitChange,
    onCommit: onSplitCommit,
  });

  return (
    <div
      {...props}
      ref={(el) => pane.attachContainer(el)}
      className={`relative flex select-none overflow-hidden rounded-[14px] border border-border bg-background ${
        isHorizontal ? "flex-row" : "flex-col"
      } ${className}`}
    >
      {/* First Pane */}
      <div
        ref={(el) => pane.attachFirstPane(el)}
        className={`relative min-h-0 min-w-0 overflow-hidden ${
          pane.collapsed === "first" ? "pointer-events-none" : ""
        }`}
        style={{ flexBasis: `${defaultSplit}%` }}
      >
        <div className="size-full overflow-auto">{first}</div>
      </div>

      {/* 1px thin line Divider Container */}
      <div
        className={`relative z-10 shrink-0 touch-none ${
          isHorizontal ? "w-px cursor-col-resize" : "h-px cursor-row-resize"
        }`}
      >
        {/* Full thin line Line */}
        <div
          className={`absolute inset-0 bg-border transition-colors ${
            pane.dragging ? "bg-primary" : "hover:bg-primary/70"
          }`}
        />

        {/* Dead-Centered Draggable Grab Handle Button */}
        <button
          ref={(el) => pane.attachDivider(el)}
          {...pane.dividerProps}
          type="button"
          role="separator"
          disabled={disabled}
          aria-orientation={isHorizontal ? "vertical" : "horizontal"}
          aria-valuenow={Math.round(split ?? defaultSplit)}
          aria-valuemin={minSize}
          aria-valuemax={maxSize}
          aria-label="Resize split panes"
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            transform: "translate(-50%, -50%)",
            touchAction: "none",
          }}
          className={`group flex items-center justify-center rounded-full border border-border bg-background text-muted-foreground transition-colors hover:border-primary/50 hover:text-foreground active:scale-95 disabled:cursor-default disabled:opacity-40 before:absolute before:-inset-3 before:content-[''] ${
            isHorizontal
              ? "h-8 w-4.5 cursor-col-resize"
              : "h-4.5 w-8 cursor-row-resize"
          } ${INTERACTION_FOCUS}`}
        >
          <GripVertical className="size-3.5 opacity-60 transition-opacity group-hover:opacity-100" />
        </button>

        {/* Optional Collapsible Controls */}
        {collapsible && !pane.dragging && (
          <div
            style={{
              position: "absolute",
              left: isHorizontal ? "50%" : "12px",
              top: isHorizontal ? "12px" : "50%",
              transform: isHorizontal
                ? "translate(-50%, 0)"
                : "translate(0, -50%)",
            }}
            className={`z-20 flex items-center gap-0.5 ${
              isHorizontal ? "flex-col" : "flex-row"
            }`}
          >
            {pane.collapsed === "first" ? (
              <button
                type="button"
                onClick={pane.expand}
                title="Restore pane"
                className="cursor-pointer rounded-full border border-border bg-surface p-0.5 text-muted-foreground transition-colors hover:text-foreground"
              >
                <ChevronRight className="size-3" />
              </button>
            ) : pane.collapsed === "second" ? (
              <button
                type="button"
                onClick={pane.expand}
                title="Restore pane"
                className="cursor-pointer rounded-full border border-border bg-surface p-0.5 text-muted-foreground transition-colors hover:text-foreground"
              >
                <ChevronLeft className="size-3" />
              </button>
            ) : (
              <div className="flex gap-0.5 opacity-0 transition-opacity group-hover:opacity-100 hover:opacity-100">
                <button
                  type="button"
                  onClick={() => pane.collapse("first")}
                  title="Collapse left"
                  className="cursor-pointer rounded border border-border bg-surface p-0.5 text-muted-foreground hover:text-foreground"
                >
                  <ChevronLeft className="size-2.5" />
                </button>
                <button
                  type="button"
                  onClick={() => pane.collapse("second")}
                  title="Collapse right"
                  className="cursor-pointer rounded border border-border bg-surface p-0.5 text-muted-foreground hover:text-foreground"
                >
                  <ChevronRight className="size-2.5" />
                </button>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Second Pane */}
      <div
        className={`relative min-h-0 min-w-0 flex-1 overflow-hidden ${
          pane.collapsed === "second" ? "pointer-events-none" : ""
        }`}
      >
        <div className="size-full overflow-auto">{second}</div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";
import {
  EASE_OUT,
  rubberBand,
  springFrames,
} from "./imported-ui-interaction-motion";

type Orientation = "horizontal" | "vertical";

type SplitPaneOptions = {
  orientation?: Orientation;
  split?: number; // 0 to 100
  defaultSplit?: number;
  minSize?: number; // default 15
  maxSize?: number; // default 85
  disabled?: boolean;
  reduced?: boolean;
  onChange?: (split: number) => void;
  onCommit?: (split: number) => void;
};

export function useSplitPane(options: SplitPaneOptions) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const firstPaneRef = React.useRef<HTMLDivElement>(null);
  const dividerRef = React.useRef<HTMLButtonElement>(null);

  const optionsRef = React.useRef(options);
  React.useLayoutEffect(() => {
    optionsRef.current = options;
  });

  const [dragging, setDragging] = React.useState(false);
  const [collapsed, setCollapsed] = React.useState<"first" | "second" | null>(
    null,
  );

  const gesture = React.useRef<{
    id: number;
    startSplit: number;
    currentSplit: number;
    containerSize: number;
    containerStart: number;
  } | null>(null);

  const min = options.minSize ?? 15;
  const max = options.maxSize ?? 85;

  const paint = React.useCallback((splitPercent: number, animate: boolean) => {
    const o = optionsRef.current;
    const pane = firstPaneRef.current;
    if (pane) {
      pane.style.transition =
        animate && !o.reduced ? `flex-basis 380ms ${EASE_OUT}` : "none";
      pane.style.flexBasis = `${splitPercent}%`;
    }
    dividerRef.current?.setAttribute(
      "aria-valuenow",
      String(Math.round(splitPercent)),
    );
  }, []);

  const commit = React.useCallback(
    (splitPercent: number, animate = true) => {
      const clean = Math.max(min, Math.min(max, splitPercent));
      paint(clean, animate);
      setCollapsed(null);
      optionsRef.current.onChange?.(clean);
      optionsRef.current.onCommit?.(clean);
    },
    [min, max, paint],
  );

  const collapse = React.useCallback(
    (side: "first" | "second") => {
      const pane = firstPaneRef.current;
      if (!pane) return;
      setCollapsed(side);
      const targetPercent = side === "first" ? 0 : 100;
      paint(targetPercent, true);
      optionsRef.current.onChange?.(targetPercent);
      optionsRef.current.onCommit?.(targetPercent);
    },
    [paint],
  );

  const expand = React.useCallback(() => {
    setCollapsed(null);
    commit(optionsRef.current.defaultSplit ?? 50, true);
  }, [commit]);

  const snapCycle = React.useCallback(() => {
    const o = optionsRef.current;
    const current = o.split ?? o.defaultSplit ?? 50;
    let next = 50;
    if (Math.abs(current - 50) < 3) next = 25;
    else if (Math.abs(current - 25) < 3) next = 75;
    else next = 50;
    commit(next, true);
  }, [commit]);

  const finish = React.useCallback(
    (cancelled: boolean) => {
      const g = gesture.current;
      if (!g) return;
      gesture.current = null;
      setDragging(false);

      if (cancelled) {
        paint(g.startSplit, true);
        optionsRef.current.onChange?.(g.startSplit);
      } else {
        // If release was in rubber-band territory beyond min or max, spring back smoothly
        const o = optionsRef.current;
        const current = g.currentSplit;
        if (current < min || current > max) {
          const target = current < min ? min : max;
          const pane = firstPaneRef.current;
          if (pane && !o.reduced) {
            const frames = springFrames(current, target, 0, 480);
            const keyframes = frames.map((f) => ({ flexBasis: `${f.value}%` }));
            const anim = pane.animate(keyframes, {
              duration: 480,
              fill: "forwards",
            });
            anim.onfinish = () => {
              pane.style.flexBasis = `${target}%`;
              anim.cancel();
              commit(target, false);
            };
          } else {
            commit(target, false);
          }
        } else {
          commit(g.currentSplit, false);
        }
      }
    },
    [min, max, commit, paint],
  );

  React.useLayoutEffect(() => {
    if (!gesture.current && collapsed === null) {
      const val = options.split ?? options.defaultSplit ?? 50;
      paint(val, true);
    }
  }, [options.split, options.defaultSplit, options.reduced, collapsed, paint]);

  const startDrag = React.useCallback(
    (event: React.PointerEvent<HTMLButtonElement>) => {
      if (event.button !== 0 || !event.isPrimary || optionsRef.current.disabled)
        return;
      const container = containerRef.current;
      if (!container) return;

      const rect = container.getBoundingClientRect();
      const isHorizontal = optionsRef.current.orientation !== "vertical";
      const containerSize = isHorizontal ? rect.width : rect.height;
      const containerStart = isHorizontal ? rect.left : rect.top;

      event.currentTarget.setPointerCapture(event.pointerId);
      event.currentTarget.focus({ preventScroll: true });

      const currentSplit =
        optionsRef.current.split ?? optionsRef.current.defaultSplit ?? 50;

      gesture.current = {
        id: event.pointerId,
        startSplit: currentSplit,
        currentSplit,
        containerSize: Math.max(1, containerSize),
        containerStart,
      };

      setDragging(true);
      setCollapsed(null);
      paint(currentSplit, false);
    },
    [paint],
  );

  const onPointerMove = React.useCallback(
    (event: React.PointerEvent<HTMLButtonElement>) => {
      const g = gesture.current;
      const o = optionsRef.current;
      if (!g || g.id !== event.pointerId) return;

      const isHorizontal = o.orientation !== "vertical";
      const clientPos = isHorizontal ? event.clientX : event.clientY;
      const rawPercent =
        ((clientPos - g.containerStart) / g.containerSize) * 100;

      // Rubber-band resistance curve beyond min/max limits
      let dampedPercent = rawPercent;
      if (rawPercent < min) {
        const overflow = min - rawPercent;
        dampedPercent = min - rubberBand(overflow, 25, 0.4);
      } else if (rawPercent > max) {
        const overflow = rawPercent - max;
        dampedPercent = max + rubberBand(overflow, 25, 0.4);
      }

      g.currentSplit = dampedPercent;
      paint(dampedPercent, false);
      o.onChange?.(dampedPercent);
    },
    [min, max, paint],
  );

  const onKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLButtonElement>) => {
      if (event.key === "Escape") {
        event.preventDefault();
        finish(true);
        return;
      }

      const isHorizontal = optionsRef.current.orientation !== "vertical";
      const prevKey = isHorizontal ? "ArrowLeft" : "ArrowUp";
      const nextKey = isHorizontal ? "ArrowRight" : "ArrowDown";

      if (![prevKey, nextKey, "Home", "End", "Enter"].includes(event.key))
        return;
      event.preventDefault();

      if (event.key === "Enter") {
        snapCycle();
        return;
      }

      const current =
        optionsRef.current.split ?? optionsRef.current.defaultSplit ?? 50;
      if (event.key === "Home") {
        commit(min);
        return;
      }
      if (event.key === "End") {
        commit(max);
        return;
      }

      const mult = event.shiftKey ? 10 : 1;
      const delta = (event.key === nextKey ? 1 : -1) * mult;
      commit(current + delta);
    },
    [min, max, snapCycle, commit, finish],
  );

  const attachContainer = React.useCallback((el: HTMLDivElement | null) => {
    containerRef.current = el;
  }, []);
  const attachFirstPane = React.useCallback((el: HTMLDivElement | null) => {
    firstPaneRef.current = el;
  }, []);
  const attachDivider = React.useCallback((el: HTMLButtonElement | null) => {
    dividerRef.current = el;
  }, []);

  const onPointerUp = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(false);
    },
    [finish],
  );
  const onPointerCancel = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onLostPointerCapture = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onBlur = React.useCallback(() => finish(true), [finish]);

  const dividerProps = React.useMemo(
    () => ({
      onPointerDown: startDrag,
      onPointerMove,
      onPointerUp,
      onPointerCancel,
      onLostPointerCapture,
      onDoubleClick: snapCycle,
      onBlur,
      onKeyDown,
    }),
    [
      startDrag,
      onPointerMove,
      onPointerUp,
      onPointerCancel,
      onLostPointerCapture,
      snapCycle,
      onBlur,
      onKeyDown,
    ],
  );

  return {
    attachContainer,
    attachFirstPane,
    attachDivider,
    dragging,
    collapsed,
    collapse,
    expand,
    snapCycle,
    dividerProps,
  };
}

